import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import type { Db, Query, Row } from "../src/db.ts";
import { TicketEvents } from "../src/tickets/events.ts";
import { TicketService } from "../src/tickets/service.ts";

// Integration harness for the SQL database. It keeps the guarantees the real one gives, and
// no more: WHERE, ORDER BY and LIMIT are honoured, but without ORDER BY rows come back in
// primary-key order (an index scan), not insertion order. With random UUID keys that is
// effectively shuffled, as it is in production.
function sqlDatabase(): Db {
    const tables = new Map<string, Row[]>();
    return {
        async insert(table, row) {
            await tick();
            const rows = tables.get(table) ?? [];
            if (rows.some((r) => r.id === row.id)) throw new Error(`duplicate key ${row.id}`);
            tables.set(table, [...rows, { ...row }]);
        },
        async select(table, q: Query) {
            await tick();
            const cmp = (a: Row, b: Row, col: string) => String(a[col]).localeCompare(String(b[col]));
            let rows = (tables.get(table) ?? []).filter((r) => Object.entries(q.where).every(([k, v]) => r[k] === v));
            rows = q.orderBy
                ? rows.sort((a, b) => cmp(a, b, q.orderBy!.column) * (q.orderBy!.direction === "asc" ? 1 : -1))
                : rows.sort((a, b) => cmp(a, b, "id"));
            return rows.slice(0, q.limit ?? rows.length).map((r) => ({ ...r }));
        },
    };
}

function setup() {
    let n = 0;
    // Deterministic stand-in for random UUIDs.
    const newId = () => ((++n * 2654435761) >>> 0).toString(16).padStart(8, "0");
    let clock = new Date("2026-11-19T09:00:00Z");
    const service = new TicketService(new TicketEvents(sqlDatabase(), newId), () => clock);
    const at = (hhmm: string) => (clock = new Date(`2026-11-19T${hhmm}:00Z`));
    return { service, at };
}

const policy = { firstResponseMinutes: 30 };

test("a new ticket is waiting for an agent", async () => {
    const { service } = setup();
    await service.open("T-1", "cust:ana", "My order arrived broken");
    assert.equal(await service.status("T-1"), "awaiting_agent");
    await assert.rejects(service.status("T-404"), /unknown ticket/);
});

test("status follows the most recent event", async () => {
    const { service, at } = setup();
    await service.open("T-1", "cust:ana", "Broken order");
    at("09:10");
    await service.agentReply("T-1", "agent:sam", "Sorry! Photo please?");
    assert.equal(await service.status("T-1"), "awaiting_customer");
    at("09:40");
    await service.customerMessage("T-1", "cust:ana", "Attached");
    assert.equal(await service.status("T-1"), "awaiting_agent");
    at("10:00");
    await service.close("T-1", "agent:sam");
    assert.equal(await service.status("T-1"), "closed");
});

test("the timeline lists events in the order they happened", async () => {
    const { service, at } = setup();
    await service.open("T-1", "cust:ana", "Broken order");
    at("09:12");
    await service.agentReply("T-1", "agent:sam", "Photo please?");
    at("09:20");
    await service.customerMessage("T-1", "cust:ana", "Attached");
    at("09:25");
    await service.agentReply("T-1", "agent:sam", "Refund issued");
    at("09:26");
    await service.close("T-1", "agent:sam");
    const lines = await service.timeline("T-1");
    console.log("timeline:", lines);
    assert.deepEqual(lines, [
        "09:00 cust:ana opened",
        "09:12 agent:sam agent_reply",
        "09:20 cust:ana customer_message",
        "09:25 agent:sam agent_reply",
        "09:26 agent:sam closed",
    ]);
});

test("first response time is measured to the first agent reply", async () => {
    const { service, at } = setup();
    await service.open("T-2", "cust:li", "Cannot log in");
    at("09:18");
    await service.agentReply("T-2", "agent:kim", "Try resetting your password");
    at("09:50");
    await service.customerMessage("T-2", "cust:li", "Still nothing");
    at("10:45");
    await service.agentReply("T-2", "agent:kim", "Unlocked your account");
    const sla = await service.sla("T-2", policy);
    assert.deepEqual([sla.respondedAfterMinutes, sla.breached], [18, false]);
});

test("a late first reply breaches the SLA even if later replies are quick", async () => {
    const { service, at } = setup();
    await service.open("T-3", "cust:bo", "Charged twice");
    at("09:30");
    await service.customerMessage("T-3", "cust:bo", "Hello?");
    at("09:45");
    await service.agentReply("T-3", "agent:sam", "Looking now");
    at("09:46");
    await service.customerMessage("T-3", "cust:bo", "Thanks");
    at("09:47");
    await service.agentReply("T-3", "agent:sam", "Refunded");
    const sla = await service.sla("T-3", policy);
    assert.deepEqual([sla.respondedAfterMinutes, sla.breached], [45, true]);
});

test("an unanswered ticket breaches once the window has passed", async () => {
    const { service, at } = setup();
    await service.open("T-4", "cust:ana", "Where is my parcel?");
    at("09:29");
    assert.equal((await service.sla("T-4", policy)).breached, false);
    at("09:31");
    const sla = await service.sla("T-4", policy);
    assert.deepEqual([sla.breached, sla.respondedAfterMinutes, sla.dueAt.toISOString()], [true, null, "2026-11-19T09:30:00.000Z"]);
});

test("one ticket's history never includes another ticket's events", async () => {
    const { service, at } = setup();
    await service.open("T-5", "cust:ana", "A");
    await service.open("T-6", "cust:li", "B");
    at("09:05");
    await service.agentReply("T-6", "agent:kim", "Hi");
    assert.deepEqual(await service.timeline("T-5"), ["09:00 cust:ana opened"]);
    assert.equal(await service.status("T-5"), "awaiting_agent");
});
